/* Scoped review usability: review objects, never mutate an unrelated inbox item. */
const urReview={selected:{},history:[]};
function urReviewItems(pid){return WI.filter(w=>w.p===pid&&w.s==='NEEDS_HUMAN_REVIEW');}
function urReviewSelect(pid,id){if(!urReviewItems(pid).some(w=>w.id===id))return;urReview.selected[pid]=id;route();}
PAGES.review=arg=>{const pid=arg||CURPROJ||'p1',items=urReviewItems(pid);let w=items.find(w=>w.id===urReview.selected[pid]);if(!w)w=items[0];urReview.selected[pid]=w?.id||null;return head(projectName(pid),'评审台','仅展示本项目待团队裁决的工作项；原型操作记录在浏览器内存中。')+card('待评审队列',items.length?cpPaged('review-'+pid,['工作项','执行者','完成阶梯','操作'],items.map(item=>[`<a href="#/workitem/${item.id}">${item.id} · ${qaEsc(item.t)}</a>`,who(item.who),ladder(item.l),`<button class="btn ${w.id===item.id?'primary':''}" onclick="urReviewSelect('${pid}','${item.id}')">${w.id===item.id?'当前选中':'评审此项'}</button>`])):'<div class="empty">本项目没有待评审工作项；尚未验证的声明不能直接通过团队裁决。</div>')+(w?card(w.id+' · '+qaEsc(w.t),`<div class="stack"><div class="row wrap">${who(w.who)}${ladder(w.l)}<span class="badge b-info">ROLE:delivery_lead · Morgan</span></div><p>先查看该工作项的完成声明、证据、验证局限与内部反馈，再作出裁决。</p><a class="btn" href="#/workitem/${w.id}">查看声明与证据</a><label class="stack small">裁决理由<textarea id="ur-review-reason" maxlength="2000" class="input" rows="3"></textarea></label><div class="row wrap"><button class="btn primary" onclick="urReviewApprove('${pid}','${w.id}')">通过 ${w.id}</button><button class="btn" onclick="urReviewReject('${pid}','${w.id}','REQUEST_CHANGES')">要求修改</button><button class="btn danger" onclick="urReviewReject('${pid}','${w.id}','REJECT')">拒绝</button></div><div id="ur-review-error" role="alert"></div></div>`):'')+card('本次裁决记录',qaTable(['工作项','结果','理由','主体'],urReview.history.filter(h=>h.project===pid).map(h=>[h.object,h.decision,qaEsc(h.reason),'Morgan · 人类'])));};
function urReviewCheck(pid,id){const w=WI.find(w=>w.id===id);return VIEWER==='team'&&w&&w.p===pid&&w.s==='NEEDS_HUMAN_REVIEW'&&w.l>=2?w:null;}
function urReviewError(message){const e=document.getElementById('ur-review-error');if(e)e.textContent=message;else toast(message);}
function urReviewRecord(w,decision,reason,extra={}){const event={action:'delivery.decision_'+decision.toLowerCase(),object:w.id,project:w.p,decision,reason,actor:'morgan',authority:'ROLE:delivery_lead',demo:true,...extra};urReview.history.push(event);if(typeof cpState!=='undefined')cpState.logs.push(event);for(let i=INBOX.length-1;i>=0;i--)if(INBOX[i].k==='WORK_ITEM_REVIEW'&&(INBOX[i].object===w.id||INBOX[i].work_item_id===w.id||INBOX[i].t.includes(w.id)))INBOX.splice(i,1);}
function urReviewApprove(pid,id){const w=urReviewCheck(pid,id);if(!w)return urReviewError('工作项或项目已变化；只可接受本项目已验证的待评审工作项。');const reason=document.getElementById('ur-review-reason').value.trim();w.s='ACCEPTED';w.l=3;urSyncProjectWork(w);urReviewRecord(w,'APPROVED',reason||'已核对当前声明与证据');route();toast('已模拟接受 '+id+' · L3；相关裁决待办已关闭');}
function urReviewReject(pid,id,decision){const w=urReviewCheck(pid,id);if(!w)return urReviewError('工作项或项目状态已变化，请重新选择。');openModal(`<div class="modal-h"><h3>${decision==='REJECT'?'拒绝':'要求修改'} · ${id}</h3></div><div class="modal-b stack"><p>质量反馈产生该工作项的返工分支；范围变更请从任务详情发起，不会在此静默修改需求基线。</p><label class="stack small">反馈类别<select id="ur-reject-category" class="select"><option value="FUNCTIONAL_DEFECT">功能缺陷</option><option value="REQUIREMENT_DEVIATION">需求偏差</option><option value="STYLE">样式</option><option value="PERFORMANCE">性能</option><option value="SECURITY">安全</option><option value="OTHER">其他</option></select></label><label class="stack small">位置<input class="input" id="ur-reject-location" maxlength="500"></label><label class="stack small">期望（必填）<input class="input" id="ur-reject-expectation" maxlength="2000"></label><label class="stack small">详情 / 理由（必填）<textarea class="input" id="ur-reject-reason" maxlength="2000"></textarea></label><div id="ur-reject-error" role="alert"></div></div><div class="modal-f"><button class="btn" onclick="closeModal()">取消</button><button class="btn danger" onclick="urReviewRejectSave('${pid}','${id}','${decision}')">提交反馈</button></div>`);}
function urReviewRejectSave(pid,id,decision){const w=urReviewCheck(pid,id),reason=document.getElementById('ur-reject-reason').value.trim(),expectation=document.getElementById('ur-reject-expectation').value.trim();if(!w||!reason||!expectation){document.getElementById('ur-reject-error').textContent=!w?'项目或工作项状态已变化，请重新加载。':'期望和反馈理由必填。';return;}const feedback={classification:'QUALITY_REJECTION',category:document.getElementById('ur-reject-category').value,location:document.getElementById('ur-reject-location').value.trim(),expectation,reason};w.s='REWORK';w.br=(w.br||0)+1;w.feedback=feedback;urSyncProjectWork(w);urReviewRecord(w,decision,reason,{feedback});closeModal();route();toast('已记录 '+id+' 反馈，并创建模拟返工分支 #'+w.br);}
/* Old shortcut callers still act on the explicitly selected scoped work item. */
approve=function(){const pid=CURPROJ||'p1',id=urReview.selected[pid];if(!id)return toast('请先在本项目评审台选中工作项');urReviewApprove(pid,id);};
const urMembers={query:'',page:0,size:20};
function urMemberFilter(kind){MF=kind;urMembers.page=0;route();}
function urMemberQuery(value){urMembers.query=value.trim();urMembers.page=0;route();}
PAGES.members=()=>{const matches=MEMBERS.filter(r=>{const kind=originOf(r[0]),p=PEOPLE[r[0]];return (MF==='all'||MF===kind||MF==='ai'&&(kind==='spawned'||kind==='orphan'))&&[p.n,r[2],r[3],r[4]].join(' ').toLowerCase().includes(urMembers.query.toLowerCase());});const pages=Math.max(1,Math.ceil(matches.length/urMembers.size));urMembers.page=Math.min(urMembers.page,pages-1);const visible=matches.slice(urMembers.page*urMembers.size,(urMembers.page+1)*urMembers.size);return head('团队','成员与 Agent','只渲染当前页；真实数据按规格经服务端过滤与分页。',cpButton('新建 Agent','newAgent()','primary'))+`<div class="row wrap">${[['all','全部'],['person','人类'],['human','人工创建 Agent'],['ai','AI 创建 Agent'],['orphan','孤儿']].map(([kind,label])=>`<button class="chip ${MF===kind?'on':''}" aria-pressed="${MF===kind}" onclick="urMemberFilter('${kind}')">${label}</button>`).join('')}<label>搜索名称、职责或机器<input class="input" value="${qaEsc(urMembers.query)}" onchange="urMemberQuery(this.value)"></label><label>每页<select class="select" onchange="urMembers.size=Number(this.value);urMembers.page=0;route()"><option ${urMembers.size===20?'selected':''}>20</option><option ${urMembers.size===50?'selected':''}>50</option></select></label></div>`+card('成员列表',qaTable(['成员','来源','职责','运行时 / 机器','状态','操作'],visible.map(r=>[who(r[0]),PEOPLE[r[0]].k==='a'?OR(r[0]):'人类',qaEsc(r[2]),qaEsc(r[3])+' / '+qaEsc(r[4]),S(r[7]),PEOPLE[r[0]].k==='a'?`<a class="btn sm" href="#/agent/${r[0]}">详情</a>`:'—']))+(matches.length?'':'<div class="empty">没有匹配成员，请清空搜索或切换筛选。</div>'))+`<div class="row wrap"><button class="btn" ${urMembers.page===0?'disabled':''} onclick="urMembers.page--;route()">上一页</button><span>${matches.length} 条 · 第 ${urMembers.page+1}/${pages} 页</span><button class="btn" ${urMembers.page>=pages-1?'disabled':''} onclick="urMembers.page++;route()">下一页</button></div>`;};
const urKnowledge={query:'导出 金额',scope:'all',type:'all'};
function urKnowledgeSet(key,value){urKnowledge[key]=value.trim();route();}
PAGES.knowledge=()=>{const words=urKnowledge.query.split(/\s+/).filter(Boolean),sources=Object.entries(gvSources).filter(([,s])=>(urKnowledge.scope==='all'||urKnowledge.scope==='p1'&&s.scope.includes('账单中心'))&&(urKnowledge.type==='all'||s.type===urKnowledge.type)).map(([id,s])=>({id,s,hits:words.filter(word=>(s.title+' '+s.content.join(' ')).toLowerCase().includes(word.toLowerCase())).length})).filter(r=>!words.length||r.hits===words.length);return head('记忆与知识','知识库','检索本地可见样例；展示命中词数，不冒充真实全文排名。',cpLink('knowledge-settings','知识设置')+cpLink('memory-review','记忆待审')+cpLink('retrieval-debug','检索调试'))+`<form onsubmit="event.preventDefault();urKnowledgeSet('query',document.getElementById('ur-knowledge-query').value)"><div class="row wrap"><label class="grow">搜索知识<input id="ur-knowledge-query" class="input" value="${qaEsc(urKnowledge.query)}" placeholder="例如：导出 金额" maxlength="500"></label><label>范围<select class="select" onchange="urKnowledgeSet('scope',this.value)"><option value="all" ${urKnowledge.scope==='all'?'selected':''}>团队可见范围</option>${PROJECTS.map(p=>`<option value="${p.id}" ${urKnowledge.scope===p.id?'selected':''}>${qaEsc(p.name)}</option>`).join('')}</select></label><label>类型<select class="select" onchange="urKnowledgeSet('type',this.value)">${[['all','全部'],['反馈','反馈'],['文档','文档'],['规则记忆','规则记忆']].map(([v,l])=>`<option value="${v}" ${urKnowledge.type===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="btn primary" type="submit">搜索</button></div></form>`+card('检索结果 · '+sources.length,sources.length?qaTable(['来源','内容','命中 / 范围'],sources.map(r=>[`<a href="#/ksource/${r.id}">${qaEsc(r.s.title)}</a>`,qaEsc(r.s.content[0]),`${r.hits}/${words.length} 个查询词 · ${qaEsc(r.s.scope)}`])):'<div class="empty">没有匹配知识。减少查询词或调整范围后重试。</div>');};
const urSession={draft:null};
function newSession(){const pid=CURPROJ||'p1';urSession.draft={project:pid};urSessionConfigure();}
function urSessionConfigure(){const d=urSession.draft;cpModal('新建交互执行会话 · 1/2',`<p>项目固定：${qaEsc(projectName(d.project))}。仅浏览器内存演示，不启动真实运行时。</p><label class="stack">关联工作项<select id="ur-session-work" class="select">${WI.filter(w=>w.p===d.project&&!['ACCEPTED','CANCELLED'].includes(w.s)).map(w=>`<option value="${w.id}">${w.id} · ${qaEsc(w.t)}</option>`).join('')}</select></label><label class="stack">执行者<select id="ur-session-actor" class="select">${MEMBERS.filter(m=>!PEOPLE[m[0]].retired&&m[7]!=='STOPPED').map(m=>`<option value="${m[0]}">${qaEsc(PEOPLE[m[0]].n)} · ${qaEsc(m[2])}</option>`).join('')}</select></label><label class="stack">机器<select id="ur-session-machine" class="select">${MACHINES.filter(m=>m.st==='ONLINE').map(m=>`<option value="${m.id}">${qaEsc(m.n)} · ${qaEsc(m.rt.join(' / '))}</option>`).join('')}</select></label><label class="stack">授权模式<input class="input" value="逐项授权（只读）" readonly></label><label class="stack">初始任务说明<textarea id="ur-session-instruction" class="input" maxlength="2000"></textarea></label>`,cpButton('下一步','urSessionPreview()','primary'));}
function urSessionPreview(){const d=urSession.draft;d.work=document.getElementById('ur-session-work').value;d.actor=document.getElementById('ur-session-actor').value;d.machine=document.getElementById('ur-session-machine').value;d.instruction=document.getElementById('ur-session-instruction').value.trim();if(!d.instruction||!WI.some(w=>w.id===d.work&&w.p===d.project)||!MACHINES.some(m=>m.id===d.machine&&m.st==='ONLINE'))return cpError('选择本项目工作项、在线机器并填写任务说明。');cpModal('新建交互执行会话 · 2/2',qaKV([['项目',projectName(d.project)],['工作项',d.work],['执行者',qaEsc(PEOPLE[d.actor].n)],['机器',qaEsc(MACHINES.find(m=>m.id===d.machine).n)],['授权模式','逐项授权；未给予额外工具权限'],['任务',qaEsc(d.instruction)]])+'<div class="note info">创建后仅演示运行、暂停、结束与完成声明；没有真实代码执行或真实证据。</div>',cpButton('创建模拟会话','urSessionCreate()','primary'));}
function urSessionCreate(){const d=urSession.draft,w=WI.find(w=>w.id===d.work);if(VIEWER!=='team'||!w||w.p!==d.project||CURPROJ!==d.project||['ACCEPTED','CANCELLED'].includes(w.s)||!MACHINES.some(m=>m.id===d.machine&&m.st==='ONLINE')||PEOPLE[d.actor]?.retired)return cpError('项目、工作项或资源已变化，请取消并重新创建。');const id='exec-local-'+Date.now();chRooms.push({id,name:w.id+' · 模拟执行',project:d.project,topic:'仅原型 · '+w.id+' · 逐项授权',members:['morgan',d.actor].filter((v,i,a)=>a.indexOf(v)===i),exec:true,workItem:w.id,actor:d.actor,machine:d.machine,execStatus:'RUNNING',instruction:d.instruction,unread:0});urReview.history.push({object:w.id,project:d.project,decision:'SESSION_CREATED',reason:d.instruction});closeModal();chState.pane='middle';go('chat/'+id);}
const urChatFlow=chFlow;
chFlow=function(){const r=chRoom();if(!r.exec||!r.workItem)return urChatFlow();return `<div class="note info">仅原型 · 不执行真实代码或产生真实运行证据。</div>`+qaKV([['工作项',`<a href="#/workitem/${r.workItem}">${r.workItem}</a>`],['执行者',qaEsc(PEOPLE[r.actor].n)],['机器',qaEsc(MACHINES.find(m=>m.id===r.machine).n)],['授权','逐项授权；工具请求时需人确认'],['状态',r.execStatus],['任务',qaEsc(r.instruction)]])+`<div class="row wrap">${r.execStatus==='RUNNING'?cpButton('暂停模拟执行',`urSessionStatus('${r.id}','PAUSED')`)+cpButton('标记模拟执行结束',`urSessionStatus('${r.id}','SUCCEEDED')`):r.execStatus==='PAUSED'?cpButton('恢复模拟执行',`urSessionStatus('${r.id}','RUNNING')`):''}${r.execStatus==='SUCCEEDED'&&!r.claim?cpButton('提交完成声明',`urSessionClaim('${r.id}')`,'primary'):''}</div>`+(r.claim?`<div class="note warn">已声明完成（L1），尚未独立验证 / 接受。声明：${qaEsc(r.claim.summary)}；证据说明：${qaEsc(r.claim.evidence)}</div>`:'');};
function urSessionStatus(id,state){const r=chRooms.find(r=>r.id===id);if(!r||VIEWER!=='team'||!(['RUNNING','PAUSED'].includes(r.execStatus)))return;const valid=r.execStatus==='RUNNING'?['PAUSED','SUCCEEDED']:['RUNNING'];if(!valid.includes(state))return;r.execStatus=state;chRender();}
function urSessionClaim(id){const r=chRooms.find(r=>r.id===id);if(!r||r.execStatus!=='SUCCEEDED'||r.claim)return;cpModal('完成声明 · '+r.workItem,'<p>声明绑定当前会话的工作项；完成声明不是验证通过或团队接受。原型不自动生成证据。</p>'+cpField('完成摘要（必填）','ur-claim-summary')+cpField('证据引用 / 局限说明（必填）','ur-claim-evidence'),cpButton('记录模拟声明',`urSessionClaimSave('${id}')`,'primary'));}
function urSessionClaimSave(id){const r=chRooms.find(r=>r.id===id),w=WI.find(w=>w.id===r?.workItem),summary=cpRead('ur-claim-summary'),evidence=cpRead('ur-claim-evidence');if(VIEWER!=='team'||!r||r.execStatus!=='SUCCEEDED'||r.claim||!w||['ACCEPTED','CANCELLED'].includes(w.s)||!summary||!evidence)return cpError('填写摘要与证据局限；工作项不得已接受或取消。');r.claim={summary,evidence,actor:r.actor,demo:true};w.s='AGENT_CLAIMED_DONE';w.l=1;urSyncProjectWork(w);cpState.logs.push({action:'work_item.claimed',object:w.id,actor:r.actor,reason:summary,demo:true});closeModal();chRender();}


function urSyncProjectWork(w){const projectWork=pjWork.find(item=>item.id===w.id);if(projectWork)Object.assign(projectWork,{s:w.s,l:w.l,br:w.br,feedback:w.feedback});}
/* Each column replaces its current page, rather than accumulating cards. */
const urBoard={project:null,pages:{},size:20};
const urWorkList=PAGES.work;
function urBoardPage(pid,column,delta){if(pid!==(CURPROJ||'p1'))return;const total=WI.filter(w=>w.p===pid&&COLS.find(c=>c[0]===column)?.[2].includes(w.s)).length,max=Math.max(0,Math.ceil(total/urBoard.size)-1);urBoard.pages[column]=Math.max(0,Math.min(max,(urBoard.pages[column]||0)+delta));route();}
PAGES.work=arg=>{const pid=arg||CURPROJ||'p1';if(urBoard.project!==pid){urBoard.project=pid;urBoard.pages={};if(cpState.tables.tasks)cpState.tables.tasks.page=0;}if(cpState.workView==='list')return urWorkList(pid);return `<div class="row wrap">${cpButton('看板视图',"cpState.workView='board';route()",'primary')}${cpButton('列表视图',"cpState.workView='list';route()")}</div>`+head(projectName(pid),'任务','按状态查看任务；每列分页浏览，也可切换列表。',cpButton('新建工作项',"newWorkItem()",'primary'))+`<div class="kanban">${COLS.map(([key,title,states])=>{const items=WI.filter(w=>w.p===pid&&states.includes(w.s)),last=Math.max(0,Math.ceil(items.length/urBoard.size)-1),page=Math.min(urBoard.pages[key]||0,last);urBoard.pages[key]=page;const visible=items.slice(page*urBoard.size,(page+1)*urBoard.size);return `<section class="col" aria-label="${title}" data-work-column="${key}"><div class="col-h">${title}<span class="badge">${items.length} 条</span></div>${visible.map(w=>`<article class="wi"><div class="row"><span class="mono muted xs">${cpEsc(w.id)}</span><span style="margin-left:auto">${ladder(w.l)}</span></div><div class="t"><a href="#/workitem/${w.id}">${cpEsc(w.t)}</a></div><div class="row">${w.who?A(w.who):''}<span class="badge">${cpEsc(w.type)}</span>${w.risk==='HIGH'?S('EXECUTION_FAILED','HIGH'):''}${w.br>1?`<span class="badge b-primary">${I('git-branch')}${w.br}</span>`:''}<span style="margin-left:auto">${S(w.s)}</span></div>${w.block?`<div class="note xs" style="margin-top:8px">${cpEsc(w.block)}</div>`:''}</article>`).join('')||'<div class="empty xs">暂无工作项</div>'}${items.length>urBoard.size?`<div class="row wrap"><button class="btn sm" ${page===0?'disabled':''} onclick="urBoardPage('${pid}','${key}',-1)">上一页</button><span class="muted xs">${page+1}/${last+1} 页</span><button class="btn sm" ${page===last?'disabled':''} onclick="urBoardPage('${pid}','${key}',1)">下一页</button></div>`:''}</section>`;}).join('')}</div>`;};
